var path=MobileGame.Foundation.Editor.LaboratorySceneAssets.ScenePath;
var before=System.IO.File.ReadAllText(path);
MobileGame.Foundation.Editor.LaboratorySceneAssets.UpgradeMobileUi();
var view=UnityEngine.Object.FindFirstObjectByType<MobileGame.Presentation.LaboratoryView>();
var config=UnityEditor.AssetDatabase.LoadAssetAtPath<MobileGame.Presentation.AppConfiguration>(MobileGame.Foundation.Editor.AppSceneAssets.ConfigurationPath);
return new { sceneBytesUnchanged=before==System.IO.File.ReadAllText(path), sharedArt=view.UiAssets.Art==config.uiAssets.Art, sharedMaterial=view.UiAssets.WorldMaterial==config.uiAssets.WorldMaterial, floors=Enumerable.Range(0,4).All(i=>view.UiAssets.GetFloorTile(i)==config.uiAssets.GetFloorTile(i)), dirty=view.gameObject.scene.isDirty };
